CREATE PROCEDURE [sales].[Customer_Search] @Search NVARCHAR(250)=NULL,@IsActive BIT=NULL,@PageNumber INT=1,@PageSize INT=20 AS BEGIN SET NOCOUNT ON;IF @PageNumber<1 OR @PageSize<1 OR @PageSize>200 THROW 52001,'Invalid paging values.',1;SELECT * FROM [sales].[CustomerSummary] WHERE (@IsActive IS NULL OR [IsActive]=@IsActive) AND (@Search IS NULL OR [CustomerCode] LIKE N'%'+@Search+N'%' OR [CustomerName] LIKE N'%'+@Search+N'%' OR [GSTIN] LIKE N'%'+@Search+N'%' OR [Mobile] LIKE N'%'+@Search+N'%') ORDER BY [CustomerName] OFFSET (@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;SELECT COUNT_BIG(1)[TotalCount] FROM [sales].[CustomerSummary] WHERE (@IsActive IS NULL OR [IsActive]=@IsActive) AND (@Search IS NULL OR [CustomerCode] LIKE N'%'+@Search+N'%' OR [CustomerName] LIKE N'%'+@Search+N'%' OR [GSTIN] LIKE N'%'+@Search+N'%' OR [Mobile] LIKE N'%'+@Search+N'%');END;
